SELECT CASE WHEN s.rating >= 3.4 THEN 'high' WHEN s.rating >= 1.7 THEN 'mid' ELSE 'low' END AS rating_bucket, s.city, AVG(i.quantity) AS avg_quantity, COUNT(DISTINCT i.quantity) AS unique_products FROM inventory i INNER JOIN products p ON i.product_id = p.id INNER JOIN suppliers s ON p.supplier_id = s.id GROUP BY CASE WHEN s.rating >= 3.4 THEN 'high' WHEN s.rating >= 1.7 THEN 'mid' ELSE 'low' END, s.city;
